        i ++;
    }
    j = i + 1;
    if (j == heightSize) return 0;
    while (j < heightSize && height[j] < height[i]) {  // find end point j
        j ++;
    }
    if (j == heightSize) {
        height[i] -= 1;  // cut the bar and retry
        goto again;
    }
    if (j < heightSize) {
        for (k = i + 1; k < j; k ++) {
