    e_t *e[HF * 2];
    e_t buff[20000];
    int n;
} ht_t;

e_t *lookup(ht_t *ht, int s) {
    e_t *e = ht->e[HC(s)];
    while (e && e->s != s) e = e->next;
    return e;
}
void insert(ht_t *ht, int s) {
    e_t *e = lookup(ht, s);
    if (e) e->c ++;
    else {
        e = &ht->buff[ht->n ++];
        e->s = s;
        e->c = 1;
        e->next = ht->e[HC(s)];
        ht->e[HC(s)] = e;
    }
}
int count(ht_t *ht, int s) {
    e_t *e = lookup(ht, s);
    if (e) return e->c;
    return 0;
}
