class ProductExceptSelfNotUseDivide{

	func productExceptSelf(_ nums: [Int]) -> [Int] {

		var arr = Array.init(repeating: 1, count: nums.count)

		for i in (0..<(nums.count - 1)).reversed() {

			arr[i] = arr[i + 1] * nums[i + 1]

		}

		var left = 1
		for i in 0..<nums.count {
			if i == 0 {
				arr[i] = left * arr[i]
			} else {
				left = left * nums[i - 1]
				arr[i] = left * arr[i]
			}
		}

		return  arr
	}

