def build_list(values):
    dummy=ListNode(); cur=dummy
    for value in values: cur.next=ListNode(value); cur=cur.next
    return dummy.next

def dump_list(node):
    out=[]; seen=set()
    while node and id(node) not in seen: seen.add(id(node)); out.append(node.val); node=node.next
    return out

def build_tree(values):
    if not values or values[0] is None: return None
    root=TreeNode(values[0]); queue=deque([root]); i=1
    while queue and i < len(values):
        node=queue.popleft()
        if i<len(values) and values[i] is not None: node.left=TreeNode(values[i]); queue.append(node.left)
        i+=1
        if i<len(values) and values[i] is not None: node.right=TreeNode(values[i]); queue.append(node.right)
        i+=1
    return root

def dump_tree(root):
    if not root: return []
    out=[]; queue=deque([root])
    while queue:
        node=queue.popleft()
        if node is None: out.append(None); continue
        out.append(node.val); queue.extend((node.left,node.right))
    while out and out[-1] is None: out.pop()
    return out

