/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     struct TreeNode *left;
 *     struct TreeNode *right;
 * };
 */
int depth(struct TreeNode *node, int *m) {
    int l, r;
    if (!node) return 0;
    l = depth(node->left,  m);
    r = depth(node->right, m);
    if (*m < l + r) *m = l + r;
    if (r < l) r = l;
    return r + 1;
}
int diameterOfBinaryTree(struct TreeNode* root) {
    int m = 0;
    depth(root,  &m);
    return m;
}


