            if (x < 0 || x >= rowsz ||
                y < 0 || y >= colsz[x] ||
                v[IDX(x, y, m)]) continue;
            v[IDX(x, y, m)] = 1;
            if (type == '0') {
                if (grid[x][y] == '0') add2q(qa, x, y);
                else {
                    add2q(qb, x, y);
                    bfs(qb, qa, v, '1', grid, rowsz, colsz, m, k);
                }
            } else {
                if (grid[x][y] == '0') add2q(qb, x, y);
                else add2q(qa, x, y);
            }
        }
    }
    if (type == '1') {
        (*k) ++;
        bfs(qb, qa, v, '0', grid, rowsz, colsz, m, k);
    }
