class Subsets {
    func subsets(_ nums: [Int]) -> [[Int]] {
        var res = [[Int]](), path = [Int]()

        dfs(&res, &path, 0, nums)

        return res
    }

    private func dfs(_ res: inout [[Int]], _ path: inout [Int], _ idx: Int, _ nums: [Int]) {
