        mid = start + (end - start) / 2;
        if (nums[mid] == target) {
            i = j = mid;
            while (i > 0 && nums[i - 1] == target) {
                i --;
            }
            while (j < numsSize - 1 && nums[j + 1] == target) {
                j ++;
            }
