#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <limits.h>
#include <math.h>
/* 20. Valid Parentheses：纯 C / Objective-C .m 兼容实现 */
/*
20. Valid Parentheses

Given a string containing just the characters '(', ')', '{', '}', '[' and ']', determine if the input string is valid.

The brackets must close in the correct order, "()" and "()[]{}" are all valid but "(]" and "([)]" are not.
*/

bool isValid(char* s) {
    int l;
    char *stack, c;
    int sp = 0;

    if (!s || !*s) return true;

    l = strlen(s);
    stack = malloc(l * sizeof(char));
    //assert(stack);
    while (c = *s ++) {
        switch (c) {
            case '(':
            case '{':
            case '[':
                stack[sp ++] = c;
                break;
            case ')':
                if (sp == 0 || stack[-- sp] != '(') { free(stack); return false; }
                break;
            case '}':
                if (sp == 0 || stack[-- sp] != '{') { free(stack); return false; }
                break;
            case ']':
                if (sp == 0 || stack[-- sp] != '[') { free(stack); return false; }
                break;
            default:
                break;
        }
    }

    free(stack);
    return sp == 0 ? true : false;
}


