class PerfectSquares {
    func numSquares(n: Int) -> Int {
        guard n > 0 else {
            return 0
        }

        var leastNums = [Int](count: n + 1, repeatedValue: Int.max)
        leastNums[0] = 0

        for i in 1...n {
            for j in 1...i  {
                if j * j > i {
                    break
                }
                leastNums[i] = min(leastNums[i], leastNums[i - j * j] + 1)
