    if not values or values[0] is None: return None
    root=TreeNode(values[0]); queue=deque([root]); i=1
    while queue and i < len(values):
        node=queue.popleft()
        if i<len(values) and values[i] is not None: node.left=TreeNode(values[i]); queue.append(node.left)
        i+=1
        if i<len(values) and values[i] is not None: node.right=TreeNode(values[i]); queue.append(node.right)
